public class Main {
    public static void main(String[] args) {
        String s = "abc";
        String t = s.concat("d");      // returns a NEW String
        s.toUpperCase();               // result thrown away, s is untouched
        System.out.println("s = " + s + ", t = " + t);
        System.out.println("same object? " + (s == t));

        // Hash code is cached because the content can never change
        System.out.println("hash of s: " + s.hashCode());

        // A String used as a key stays findable
        java.util.Map<String, Integer> m = new java.util.HashMap<>();
        m.put(s, 1);
        s = s + "x";                   // s now points to a different object
        System.out.println("old key still found: " + m.get("abc"));
        System.out.println("new s = " + s);
    }
}

public class Main {
    public static void main(String[] args) {
        String a = "java";
        String b = "java";                    // same pooled literal
        String c = new String("java");        // new heap object
        String d = "ja";
        String e = d + "va";                  // built at runtime

        System.out.println("a == b      : " + (a == b));
        System.out.println("a == c      : " + (a == c));
        System.out.println("a == e      : " + (a == e));
        System.out.println("a.equals(c) : " + a.equals(c));
        System.out.println("a.equals(e) : " + a.equals(e));

        // Null-safe comparison: put the constant first
        String input = null;
        System.out.println("\"java\".equals(null): " + "java".equals(input));
        System.out.println("Objects.equals(null, null): " + java.util.Objects.equals(input, null));
    }
}

public class Main {
    public static void main(String[] args) {
        String lit = "pool";
        String built = new StringBuilder("po").append("ol").toString();
        System.out.println("literal == built      : " + (lit == built));

        String interned = built.intern();     // returns the pooled instance
        System.out.println("literal == interned   : " + (lit == interned));

        // Compile-time constants are pooled automatically
        String x = "po" + "ol";
        System.out.println("literal == constant   : " + (lit == x));

        // A final variable is also a compile-time constant
        final String p = "po";
        String y = p + "ol";
        System.out.println("literal == final-concat: " + (lit == y));

        String q = "po";                      // not final: runtime concat
        String z = q + "ol";
        System.out.println("literal == runtime-concat: " + (lit == z));
    }
}

public class Main {
    public static void main(String[] args) {
        String pooled = "hello";              // one object in the pool
        String copy = new String("hello");    // a second, separate String object

        System.out.println("copy == pooled        : " + (copy == pooled));
        System.out.println("copy.equals(pooled)   : " + copy.equals(pooled));
        System.out.println("copy.intern() == pooled: " + (copy.intern() == pooled));

        // Two new Strings are always two different objects
        String c2 = new String("hello");
        System.out.println("copy == c2            : " + (copy == c2));

        // identityHashCode differs for different objects
        System.out.println("distinct identities   : "
            + (System.identityHashCode(copy) != System.identityHashCode(pooled)));
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 5;

        // Each += copies the whole text so far: O(n^2) characters copied overall
        String s = "";
        long copied = 0;
        for (int i = 0; i < n; i++) {
            copied += s.length() + 1;         // size of the new String created
            s += i;
        }
        System.out.println("concat result: " + s + ", chars copied: " + copied);

        // StringBuilder appends into one growing buffer: O(n) amortised
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            sb.append(i);
        }
        System.out.println("builder result: " + sb);
        System.out.println("same text: " + s.equals(sb.toString()));

        // StringBuilder does not override equals: identity comparison
        System.out.println("sb.equals(copy of sb): "
            + sb.equals(new StringBuilder(sb)));
        System.out.println("contentEquals: " + s.contentEquals(sb));
    }
}

public class Main {
    public static void main(String[] args) {
        StringBuilder sb = new StringBuilder();
        System.out.println("start capacity: " + sb.capacity());   // 16 by default

        int last = sb.capacity();
        for (int i = 1; i <= 150; i++) {
            sb.append('x');
            if (sb.capacity() != last) {      // report each regrowth
                System.out.println("length " + i + ": " + last
                    + " -> " + sb.capacity() + " (old*2+2)");
                last = sb.capacity();
            }
        }

        // Pre-sizing avoids any regrowth
        StringBuilder big = new StringBuilder(200);
        for (int i = 0; i < 150; i++) big.append('x');
        System.out.println("pre-sized capacity still: " + big.capacity());

        // new StringBuilder('a') is the int 97, i.e. capacity 97, not text "a"
        StringBuilder odd = new StringBuilder('a');
        System.out.println("capacity=" + odd.capacity() + " text=[" + odd + "]");
        sb.trimToSize();
        System.out.println("after trimToSize: " + sb.capacity());
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Collections hold objects, so primitives are boxed
        List<Integer> nums = new ArrayList<>();
        nums.add(10);
        nums.add(20);
        System.out.println("list: " + nums);

        // null means "no value"; a primitive cannot say that
        Integer maybeAge = null;
        System.out.println("maybeAge: " + maybeAge);

        // Utility methods and constants
        System.out.println("parseInt(\"42\")   : " + Integer.parseInt("42"));
        System.out.println("valueOf(\"42\")    : " + Integer.valueOf("42"));
        System.out.println("MAX_VALUE        : " + Integer.MAX_VALUE);
        System.out.println("compare(3, 9)    : " + Integer.compare(3, 9));
        System.out.println("isDigit('7')     : " + Character.isDigit('7'));

        // Wrappers are immutable: += creates a new object
        Integer x = 5;
        Integer before = x;
        x += 1;
        System.out.println("x=" + x + ", old reference still " + before);
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        // 1. remove(int index) versus remove(Object)
        List<Integer> list = new ArrayList<>(List.of(5, 1, 7));
        list.remove(1);                       // removes INDEX 1 (value 1)
        System.out.println("after remove(1): " + list);
        list.remove(Integer.valueOf(7));      // removes the VALUE 7
        System.out.println("after remove(Integer.valueOf(7)): " + list);

        // 2. Map<Long,...>.get(int) never matches
        Map<Long, String> m = new HashMap<>();
        m.put(5L, "five");
        System.out.println("get(5)  : " + m.get(5));
        System.out.println("get(5L) : " + m.get(5L));

        // 3. Unboxing null throws NPE
        Map<String, Integer> counts = new HashMap<>();
        try {
            int n = counts.get("missing");
            System.out.println(n);
        } catch (NullPointerException e) {
            System.out.println("NPE from unboxing null");
        }

        // 4. Ternary with int and null Integer
        Integer none = null;
        try {
            Integer r = true ? none : 0;      // type is int, so none is unboxed
            System.out.println(r);
        } catch (NullPointerException e) {
            System.out.println("NPE from ternary");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Integer a = 100, b = 100;             // autoboxing uses Integer.valueOf
        Integer c = 1000, d = 1000;
        Integer e = 127, f = 127;
        Integer g = 128, h = 128;

        System.out.println("100  == 100 : " + (a == b));
        System.out.println("127  == 127 : " + (e == f));
        System.out.println("128  == 128 : " + (g == h));
        System.out.println("1000 == 1000: " + (c == d));
        System.out.println("1000 equals : " + c.equals(d));

        // valueOf hits the cache, the constructor never does
        System.out.println("valueOf(5)==valueOf(5): "
            + (Integer.valueOf(5) == Integer.valueOf(5)));

        // Other wrappers
        Long l1 = 127L, l2 = 127L;
        Long l3 = 128L, l4 = 128L;
        System.out.println("Long 127: " + (l1 == l2) + ", Long 128: " + (l3 == l4));
        Double d1 = 1.0, d2 = 1.0;
        System.out.println("Double 1.0: " + (d1 == d2));
    }
}

import java.util.*;

public class Main {
    static class Bad {
        final int id;
        Bad(int id) { this.id = id; }
        @Override public boolean equals(Object o) {
            return o instanceof Bad && ((Bad) o).id == id;
        }
        // hashCode NOT overridden: identity hash is used
    }

    static class Good extends Bad {
        Good(int id) { super(id); }
        @Override public int hashCode() { return Integer.hashCode(id); }
    }

    public static void main(String[] args) {
        Set<Bad> bad = new HashSet<>();
        bad.add(new Bad(1));
        System.out.println("equal objects: " + new Bad(1).equals(new Bad(1)));
        System.out.println("bad set contains Bad(1): " + bad.contains(new Bad(1)));
        bad.add(new Bad(1));
        System.out.println("bad set size after adding equal again: " + bad.size());

        Set<Good> good = new HashSet<>();
        good.add(new Good(1));
        good.add(new Good(1));
        System.out.println("good set contains Good(1): " + good.contains(new Good(1)));
        System.out.println("good set size: " + good.size());
    }
}

public class Main {
    // Same spreading step HashMap uses
    static int spread(int h) { return h ^ (h >>> 16); }

    public static void main(String[] args) {
        int n = 16;                           // table size, a power of two
        String[] keys = {"apple", "banana", "cherry", "date"};
        for (String k : keys) {
            int h = k.hashCode();
            int spreadH = spread(h);
            int index = spreadH & (n - 1);    // same as spreadH % 16 for non-negative
            System.out.println(k + ": hash=" + h + " spread=" + spreadH
                + " bucket=" + index);
        }

        // Without spreading, only the low 4 bits would pick the bucket
        int h = 0x10000;                      // differs only in a high bit
        System.out.println("no spread bucket : " + (h & (n - 1)));
        System.out.println("with spread bucket: " + (spread(h) & (n - 1)));

        // Why mask works: n-1 is all ones in binary
        System.out.println("n-1 in binary: " + Integer.toBinaryString(n - 1));
    }
}

import java.util.*;

public class Main {
    record Person(String name, int age) implements Comparable<Person> {
        // Natural order: by name
        public int compareTo(Person o) { return name.compareTo(o.name); }
    }

    public static void main(String[] args) {
        List<Person> people = new ArrayList<>(List.of(
            new Person("Zoe", 30), new Person("Amy", 41),
            new Person("Bob", 30), new Person("Cid", 25)));

        Collections.sort(people);             // uses compareTo
        System.out.println("natural (name): " + people);

        // External comparators: age descending, then name ascending
        people.sort(Comparator.comparingInt(Person::age).reversed()
                              .thenComparing(Person::name));
        System.out.println("age desc, name: " + people);

        // Never subtract in compare: it overflows
        int a = Integer.MAX_VALUE, b = -1;
        System.out.println("a - b sign (wrong): " + Integer.signum(a - b));
        System.out.println("Integer.compare(a, b): " + Integer.compare(a, b));
    }
}

import java.math.BigDecimal;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        BigDecimal x = new BigDecimal("1.0");
        BigDecimal y = new BigDecimal("1.00");
        System.out.println("equals: " + x.equals(y) + ", compareTo: " + x.compareTo(y));

        Set<BigDecimal> hash = new HashSet<>(List.of(x, y));
        Set<BigDecimal> tree = new TreeSet<>(List.of(x, y));
        System.out.println("HashSet size: " + hash.size());
        System.out.println("TreeSet size: " + tree.size());

        // Length-only comparator merges different words
        Set<String> byLen = new TreeSet<>(Comparator.comparingInt(String::length));
        byLen.addAll(List.of("cat", "dog", "bird"));
        System.out.println("length comparator: " + byLen);

        // Fix: add a tie-breaker
        Set<String> fixed = new TreeSet<>(
            Comparator.comparingInt(String::length).thenComparing(Comparator.naturalOrder()));
        fixed.addAll(List.of("cat", "dog", "bird"));
        System.out.println("with tie-breaker : " + fixed);
    }
}

import java.util.*;
import java.util.concurrent.*;

public class Main {
    // A record is final, has final fields, and generates equals/hashCode
    record Point(int x, int y) {}

    public static void main(String[] args) throws Exception {
        Map<Point, Integer> counts = new ConcurrentHashMap<>();
        Thread[] ts = new Thread[4];
        for (int t = 0; t < ts.length; t++) {
            ts[t] = new Thread(() -> {
                for (int i = 0; i < 1000; i++) {
                    // merge is atomic: no lost updates
                    counts.merge(new Point(i % 3, 0), 1, Integer::sum);
                }
            });
            ts[t].start();
        }
        for (Thread t : ts) t.join();

        int total = 0;
        for (Point p : new TreeSet<>(Comparator.comparingInt(Point::x)) {{ addAll(counts.keySet()); }}) {
            System.out.println(p + " -> " + counts.get(p));
            total += counts.get(p);
        }
        System.out.println("total = " + total);
        System.out.println("equal keys: " + new Point(1, 0).equals(new Point(1, 0))
            + ", same hash: " + (new Point(1, 0).hashCode() == new Point(1, 0).hashCode()));
    }
}
